# TTL cache
Example tests miss expiry and overwrite interleavings. Design work should use existing tools without installing new packages.
class Cache:
    def __init__(self):
        self.values = {}
    def set(self, key, value, now, ttl):
        self.values[key] = (value, now + ttl)
    def get(self, key, now):
        value, expires = self.values[key]
        return value if now < expires else None
